alter table pipeline.layer1_source_operations add column previous_accepted_hash text; update pipeline.layer1_source_operations set previous_accepted_hash=last_source_hash where previous_accepted_hash is null; create or replace function public.svc_layer1_queue_context(p_run_id uuid) returns jsonb language sql stable security definer set search_path=pg_catalog,pipeline as $$ select jsonb_build_object('id',q.id,'source_id',q.source_id,'country_code',q.country_code,'mode',q.mode,'status',q.status,'expected_count',q.expected_count,'processed_count',q.processed_count,'resume_cursor',q.resume_cursor,'source_hash',q.source_hash,'previous_accepted_hash',o.previous_accepted_hash,'warning_acknowledged',q.warning_acknowledged) from pipeline.layer1_run_queue q join pipeline.layer1_source_operations o on o.source_id=q.source_id where q.id=p_run_id $$; revoke all on function public.svc_layer1_queue_context(uuid) from public,anon,authenticated; grant execute on function public.svc_layer1_queue_context(uuid) to service_role; create or replace function public.svc_layer1_run_progress(p_run_id uuid,p_status text,p_stage text,p_processed bigint default null,p_created bigint default null,p_updated bigint default null,p_unchanged bigint default null,p_rejected bigint default null,p_conflicted bigint default null,p_failed bigint default null,p_actual_job_id uuid default null,p_result jsonb default null,p_error text default null,p_source_hash text default null,p_resume_cursor bigint default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,pipeline as $$ declare v_source uuid; v_mode text; v_expected bigint; begin if p_status not in ('queued','running','completed','failed','cancelled','blocked','no_change') then raise exception 'invalid status'; end if; update pipeline.layer1_run_queue set status=p_status,current_stage=coalesce(nullif(p_stage,''),current_stage),heartbeat_at=now(),started_at=case when p_status='running' then coalesce(started_at,now()) else started_at end,completed_at=case when p_status in ('completed','failed','cancelled','blocked','no_change') then coalesce(completed_at,now()) else completed_at end,processed_count=coalesce(p_processed,processed_count),created_count=coalesce(p_created,created_count),updated_count=coalesce(p_updated,updated_count),unchanged_count=coalesce(p_unchanged,unchanged_count),rejected_count=coalesce(p_rejected,rejected_count),conflicted_count=coalesce(p_conflicted,conflicted_count),failed_count=coalesce(p_failed,failed_count),actual_job_id=coalesce(p_actual_job_id,actual_job_id),result=case when p_result is null then result else p_result end,error_text=case when p_error is null then error_text else left(p_error,1800) end,source_hash=coalesce(p_source_hash,source_hash),resume_cursor=coalesce(p_resume_cursor,resume_cursor),updated_at=now() where id=p_run_id returning source_id,mode,expected_count into v_source,v_mode,v_expected; if not found then raise exception 'run not found'; end if; if p_status in ('completed','no_change') and v_mode='apply' then update pipeline.layer1_source_operations set previous_accepted_count=coalesce(v_expected,previous_accepted_count),previous_accepted_hash=coalesce(p_source_hash,previous_accepted_hash),last_source_hash=coalesce(p_source_hash,last_source_hash),next_ingestion_at=case when ingestion_cadence_days is null then null else now()+make_interval(days=>ingestion_cadence_days) end,last_schedule_status=p_status,last_schedule_error=null,updated_at=now() where source_id=v_source; elsif p_status in ('failed','blocked') then update pipeline.layer1_source_operations set last_schedule_status=p_status,last_schedule_error=left(coalesce(p_error,p_status),1000),consecutive_failures=consecutive_failures+1,updated_at=now() where source_id=v_source; end if; return jsonb_build_object('run_id',p_run_id,'status',p_status,'stage',p_stage); end $$; revoke all on function public.svc_layer1_run_progress(uuid,text,text,bigint,bigint,bigint,bigint,bigint,bigint,bigint,uuid,jsonb,text,text,bigint) from public,anon,authenticated; grant execute on function public.svc_layer1_run_progress(uuid,text,text,bigint,bigint,bigint,bigint,bigint,bigint,bigint,uuid,jsonb,text,text,bigint) to service_role;